    @Test void fourReadyChildrenDeliverSequentiallyWithinActualSdkBudgetAndReleaseAllowsAnotherParent()throws Exception {
        try(var first=new ReadyGraph(root.resolve("four-first"));var second=new ReadyGraph(root.resolve("four-second"));var delivery=new RatisExportClient(null,first.scheduler,null,RatisExportClient.Limits.defaults())){
            var effects=new java.util.concurrent.atomic.AtomicInteger();var dependencies=denied(delivery,()->{throw new AssertionError("READY cannot reread source");},effects);
            for(var graph:List.of(first,second))try(var backend=new RatisExportBackend(graph.jobs,first.scheduler,dependencies,RatisExportBackend.Limits.defaults())){
                UUID id;try(var entries=Files.list(graph.jobs)){id=UUID.fromString(entries.filter(Files::isDirectory).findFirst().orElseThrow().getFileName().toString());}assertEquals(ExportJobs.Phase.READY,await(backend.exportStatus(id,RequestContext.batch())).phase());int offset=0;var chunks=new ArrayList<ExportJobs.Chunk>();
                while(chunks.size()<4){var page=await(backend.exportManifest(new ExportJobs.ManifestRequest(id,offset,1,ExportJobs.MIN_PAGE_BYTES),RequestContext.batch()));assertEquals(1,page.chunks().size());chunks.addAll(page.chunks());offset=page.next();assertTrue(delivery.stats().jobs()<=1);}
                assertEquals(4,chunks.size());for(var chunk:chunks){var page=await(backend.readExport(new ExportJobs.ReadRequest(chunk.id(),0,ExportJobs.MIN_PAGE_BYTES),RequestContext.batch()));assertTrue(page.bytes().length>0);await(backend.acknowledgeExport(chunk.id(),RequestContext.batch()));assertTrue(delivery.stats().jobs()<=1);}await(backend.releaseExport(id,RequestContext.batch()));assertEquals(0,delivery.stats().jobs());assertEquals(ExportJobs.Phase.RELEASED,await(backend.exportStatus(id,RequestContext.batch())).phase());assertEquals(0,effects.get());
            }
        }
    }

